import { readFileSync } from "node:fs";

import { API_URL } from "../../playwright.config";
import { expect, sample, test, uniqueName } from "../../fixtures";

type Json = Record<string, any>;

test("rejecting an extraction requires a note and returns the vendor to the member", { tag: "@REV-06" }, async ({ apiAs }) => {
  // Arrange: a member submits a vendor whose three documents are extracted
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Rev Harbor"), category: "services", contact_email: "ops@revharbor.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as Json;

  const uploads: { kind: string; file: string; name: string }[] = [
    { kind: "w9", file: "w9.txt", name: "w9.txt" },
    { kind: "insurance_certificate", file: "insurance_certificate.txt", name: "insurance_certificate.txt" },
    { kind: "contract", file: "contract.txt", name: "contract.txt" },
  ];
  const documentIds: string[] = [];
  for (const u of uploads) {
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: u.kind,
        file: { name: u.name, mimeType: "text/plain", buffer: readFileSync(sample(u.file)) },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
    documentIds.push(((await res.json()) as Json).id);
  }

  // Extraction runs in the background: wait until every document is extracted.
  for (const documentId of documentIds) {
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/documents/${documentId}`);
          return ((await res.json()) as Json).status;
        },
        { timeout: 15_000 },
      )
      .toBe("extracted");
  }

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  expect(((await submitted.json()) as Json).status).toBe("in_review");

  // Find the W-9 extraction
  const w9DocumentId = documentIds[0];
  const extractionRes = await reviewer.get(`/api/documents/${w9DocumentId}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extraction = (await extractionRes.json()) as Json;
  expect(extraction.kind).toBe("w9");
  expect(extraction.status).toBe("pending_review");

  // Act: reject without a note
  const noNote = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "reject" },
  });

  // Assert: refused
  expect(noNote.status(), await noNote.text()).toBe(422);

  // Act: reject with a note
  const withNote = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });

  // Assert: accepted, vendor returned to the member
  expect(withNote.status(), await withNote.text()).toBe(200);
  expect(((await withNote.json()) as Json).status).toBe("rejected");

  const vendorRes = await member.get(`/api/vendors/${vendor.id}`);
  expect(vendorRes.status(), await vendorRes.text()).toBe(200);
  expect(((await vendorRes.json()) as Json).status).toBe("rejected");

  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const audit = (await auditRes.json()) as Json;
  expect(audit.items.map((e: Json) => e.action)).toContain("extraction.rejected");
});
